class Solution:
    def minimumCost(self, nums: list[int], k: int) -> int:
        total = sum(nums)

        ops = 0

        if total % k == 0:
            ops += total // k
        else:
            ops += total // k + 1

        ops -= 1

        return ops*(ops + 1) // 2 % (10**9 + 7)
